const listRequests = `-- name: ListRequests :many
SELECT r.id, r.number, r.property_id, r.contract_id, r.author_id, r.author_role, r.category, r.title, r.description, r.priority, r.status, r.contractor, r.planned_date, r.result_note, r.tenant_fault, r.done_at, r.closed_at, r.created_at, r.updated_at, p.code AS property_code, c.number AS contract_number
FROM maintenance_requests r JOIN properties p ON p.id = r.property_id LEFT JOIN contracts c ON c.id = r.contract_id
WHERE (cardinality($1::text[]) = 0 OR r.status = ANY($1::text[]))
  AND ($2::uuid IS NULL OR r.property_id = $2)
  AND ($3::uuid IS NULL OR r.contract_id = $3)
  AND ($4::text IS NULL OR r.category = $4)
  AND ($5::text IS NULL OR r.priority = $5)
  AND ($6::text IS NULL OR r.number ILIKE '%' || $6 || '%' OR r.title ILIKE '%' || $6 || '%')
ORDER BY
  CASE WHEN $7::text = 'createdAt' THEN r.created_at END ASC,
  CASE WHEN $7::text = 'plannedDate' THEN r.planned_date END ASC NULLS LAST,
  CASE WHEN $7::text = '-plannedDate' THEN r.planned_date END DESC NULLS LAST,
  CASE WHEN $7::text = 'number' THEN r.number END ASC,
  CASE WHEN $7::text = '-number' THEN r.number END DESC,
  r.created_at DESC, r.id DESC
LIMIT $9 OFFSET $8
`

type ListRequestsParams struct {
	Statuses   []string
	PropertyID *uuid.UUID
	ContractID *uuid.UUID
	Category   *string
	Priority   *string
	Q          *string
	Sort       string
	Off        int32
	Lim        int32
}

type ListRequestsRow struct {
	ID             uuid.UUID
	Number         string
	PropertyID     uuid.UUID
	ContractID     *uuid.UUID
	AuthorID       uuid.UUID
	AuthorRole     string
	Category       string
	Title          string
	Description    string
	Priority       string
	Status         string
	Contractor     *string
	PlannedDate    *date.Date
	ResultNote     *string
	TenantFault    bool
	DoneAt         *time.Time
	ClosedAt       *time.Time
	CreatedAt      time.Time
	UpdatedAt      time.Time
	PropertyCode   string
	ContractNumber *string
}

func (q *Queries) ListRequests(ctx context.Context, arg ListRequestsParams) ([]ListRequestsRow, error) {
	rows, err := q.db.Query(ctx, listRequests,
		arg.Statuses,
		arg.PropertyID,
		arg.ContractID,
		arg.Category,
		arg.Priority,
		arg.Q,
		arg.Sort,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListRequestsRow{}
	for rows.Next() {
		var i ListRequestsRow
		if err := rows.Scan(
			&i.ID,
			&i.Number,
			&i.PropertyID,
			&i.ContractID,
			&i.AuthorID,
			&i.AuthorRole,
			&i.Category,
			&i.Title,
			&i.Description,
			&i.Priority,
			&i.Status,
			&i.Contractor,
			&i.PlannedDate,
			&i.ResultNote,
			&i.TenantFault,
			&i.DoneAt,
			&i.ClosedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.PropertyCode,
			&i.ContractNumber,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

